# maybe pattern: shape drawn by "missing line" — like demo's rectangle has missing cells; fill gaps in each row/col of the rectangle.
# demo: rect corners (2,2)-(7,6). Fill all border cells of that rect with 0? Already full. In test maybe fill border of bounding box of 8-shape.
def bbox(g,v):
    rows=[r for r,row in enumerate(g) if any(x==v for x in row)]; cols=[c for r,row in enumerate(g) for c,x in enumerate(row) if x==v]
    rs=[];cs=[]
    for r in rows:
        for c in range(len(g[0])):
            if g[r][c]==v: rs.append(r); cs.append(c)
    return min(rs),max(rs),min(cs),max(cs)
def f_fill(g,v=8):
    r0,r1,c0,c1=bbox(g,v)
    o=[row[:] for row in g]
    # fill top and bottom rows of bbox where v present extends? complete border lines
    for c in range(c0,c1+1):
        if g[r0][c]!=v: o[r0][c]=v
        if g[r1][c]!=v: o[r1][c]=v
    for r in range(r0,r1+1):
        if g[r][c0]!=v: o[r][c0]=v
        if g[r][c1]!=v: o[r][c1]=v
    return o
print(json.dumps(f_fill(T)))
# check on demo
print(json.dumps(f_fill(I))==json.dumps(O))

