# rule: fill straight run gaps along both axes between same-color cells with that color, including diagonals? Let's test: only horizontal/vertical.
def fill_runs(g):
    H=len(g);W=len(g[0]);o=[r[:] for r in g]
    for v in {7,9}:
        for r in range(H):
            c=0
            while c<W:
                if g[r][c]==v:
                    c0=c
                    while c<W and g[r][c]==v: c+=1
                    if c-c0>=2:
                        for cc in range(c0+1,c): o[r][cc]=v
                else: c+=1
        for c in range(W):
            r=0
            while r<H:
                if g[r][c]==v:
                    r0=r
                    while r<H and g[r][c]==v: r+=1
                    if r-r0>=2:
                        for rr in range(r0+1,r): o[rr][c]=v
                else: r+=1
    return o
